import React, { useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../services/firebaseConfig";
import {
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  Tooltip,
  Legend,
  XAxis,
  ResponsiveContainer,
} from "recharts";

export default function Dashboard() {
  const [transactions, setTransactions] = useState([]);
  const [summary, setSummary] = useState({ entradas: 0, saidas: 0, saldo: 0 });

  useEffect(() => {
    const loadTransactions = async () => {
      try {
        const snapshot = await getDocs(collection(db, "transactions"));
        const data = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));

        console.log("🔥 Dados do Firestore:", data); // <-- DEBUG AQUI

        setTransactions(data);

        const entradas = data
          .filter(
            (t) =>
              (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "entrada"
          )
          .reduce((acc, t) => acc + parseFloat(t.value || 0), 0);

        const saidas = data
          .filter(
            (t) =>
              (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "saida"
          )
          .reduce((acc, t) => acc + parseFloat(t.value || 0), 0);

        console.log("✅ Entradas:", entradas, "Saídas:", saidas);

        setSummary({ entradas, saidas, saldo: entradas - saidas });
      } catch (error) {
        console.error("Erro ao carregar transações:", error);
      }
    };

    loadTransactions();
  }, []);

  const expenseDetails = transactions
    .filter(
      (t) =>
        (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "saida"
    )
    .map((t) => ({
      name: t.category || "Sem categoria",
      value: parseFloat(t.value || 0),
      color: t.color || "#ef4444",
    }));

  const incomeDetails = transactions
    .filter(
      (t) =>
        (t.type?.toLowerCase?.() || t.tipo?.toLowerCase?.()) === "entrada"
    )
    .map((t) => ({
      name: t.category || "Sem categoria",
      value: parseFloat(t.value || 0),
      color: t.color || "#22c55e",
    }));

  const barData = [
    { name: "Entradas", valor: summary.entradas },
    { name: "Saídas", valor: summary.saidas },
  ];

  return (
    <div className="p-6 text-white">
      <h2 className="text-2xl font-bold mb-4">📊 Dashboard Financeiro</h2>

      <div className="grid grid-cols-3 gap-4 mb-6">
        <div className="bg-green-800 p-4 rounded-lg">
          Entradas: <strong>R$ {summary.entradas.toFixed(2)}</strong>
        </div>
        <div className="bg-red-800 p-4 rounded-lg">
          Saídas: <strong>R$ {summary.saidas.toFixed(2)}</strong>
        </div>
        <div
          className={`p-4 rounded-lg ${summary.saldo >= 0 ? "bg-green-600" : "bg-red-600"
            }`}
        >
          Saldo: <strong>R$ {summary.saldo.toFixed(2)}</strong>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-6">
        {/* Gráfico de Barras */}
        <div className="bg-gray-900 p-4 rounded-lg">
          <h3 className="mb-2 font-bold text-lg">Resumo Geral</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={barData}>
              <XAxis dataKey="name" tick={{ fill: "#ddd" }} />
              <Tooltip cursor={{ fill: "rgba(255,255,255,0.1)" }} />
              <Bar dataKey="valor" radius={[8, 8, 0, 0]}>
                {barData.map((entry, index) => (
                  <Cell
                    key={`bar-${index}`}
                    fill={index === 0 ? "#22c55e" : "#ef4444"}
                  />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* Gráfico de Pizza - Saídas */}
        <div className="bg-gray-900 p-4 rounded-lg">
          <h3 className="mb-2 font-bold text-lg">Saídas por Categoria</h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={expenseDetails}
                dataKey="value"
                nameKey="name"
                outerRadius={100}
              >
                {expenseDetails.map((entry, index) => (
                  <Cell key={`slice-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        </div>

        {/* Gráfico de Pizza - Entradas */}
        <div className="bg-gray-900 p-4 rounded-lg col-span-2">
          <h3 className="mb-2 font-bold text-lg">Entradas por Categoria</h3>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={incomeDetails}
                dataKey="value"
                nameKey="name"
                outerRadius={100}
              >
                {incomeDetails.map((entry, index) => (
                  <Cell key={`slice-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
}
